function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

function poem(keyword, opts){
  opts=opts||{}; var k=(keyword||'春').trim()||'春';
  var seed=opts.seed!=null?opts.seed:7;
  var r=rngFactory(seed);
  var a=['风','月','花','雪','山','水','云','星','海','林'];
  var b=['轻拂窗棂','静卧心头','低语耳边','照亮归途','沉入梦里','升起希望','流淌岁月','绽放心事'];
  var x=a[Math.floor(r()*a.length)], y=a[Math.floor(r()*a.length)], z=b[Math.floor(r()*b.length)];
  return [k+'来，'+x+'先知。', x+'过，'+y+'未觉。', z+'，'+k+'已成诗。'].join('\n');
}

var EXPORTS={poem:poem};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PoemForgePure = EXPORTS; }
